CREATE TABLE IF NOT EXISTS bashpay_users(id BIGSERIAL PRIMARY KEY,email TEXT NOT NULL UNIQUE,first_name TEXT,last_name TEXT,image_url TEXT,clerk_user_id TEXT UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bashpay_assets(id BIGSERIAL PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL,decimals INT NOT NULL DEFAULT 2,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS bashpay_wallets(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES bashpay_users(id) ON DELETE CASCADE,asset_id BIGINT NOT NULL REFERENCES bashpay_assets(id),balance NUMERIC(38,18) NOT NULL DEFAULT 0,available_balance NUMERIC(38,18) NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,asset_id));
CREATE TABLE IF NOT EXISTS bashpay_transactions(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES bashpay_users(id) ON DELETE CASCADE,type TEXT NOT NULL,status TEXT NOT NULL,amount NUMERIC(38,18) NOT NULL,currency TEXT NOT NULL,description TEXT,provider TEXT,provider_ref TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bashpay_transfers(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES bashpay_users(id) ON DELETE CASCADE,recipient TEXT NOT NULL,amount NUMERIC(38,18) NOT NULL,currency TEXT NOT NULL,fee NUMERIC(38,18) NOT NULL DEFAULT 0,destination_type TEXT NOT NULL,status TEXT NOT NULL,reference TEXT UNIQUE,provider_transfer_id TEXT,idempotency_key TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS bashpay_transfer_idem ON bashpay_transfers(user_id,idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE TABLE IF NOT EXISTS bashpay_exchange_rates(id BIGSERIAL PRIMARY KEY,from_code TEXT NOT NULL,to_code TEXT NOT NULL,rate NUMERIC(38,18) NOT NULL,source TEXT,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(from_code,to_code));
CREATE TABLE IF NOT EXISTS bashpay_exchanges(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES bashpay_users(id) ON DELETE CASCADE,from_code TEXT NOT NULL,to_code TEXT NOT NULL,amount NUMERIC(38,18) NOT NULL,result NUMERIC(38,18) NOT NULL,rate NUMERIC(38,18) NOT NULL,source TEXT NOT NULL,idempotency_key TEXT NOT NULL,reference TEXT UNIQUE,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,idempotency_key));
CREATE TABLE IF NOT EXISTS bashpay_spaces(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES bashpay_users(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT,balance NUMERIC(38,18) NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bashpay_requests(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES bashpay_users(id) ON DELETE CASCADE,amount NUMERIC(38,18),currency TEXT,description TEXT,status TEXT NOT NULL DEFAULT 'PENDING',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bashpay_alerts(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES bashpay_users(id) ON DELETE CASCADE,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bashpay_treasury(id BIGSERIAL PRIMARY KEY,asset_id BIGINT UNIQUE NOT NULL REFERENCES bashpay_assets(id),balance NUMERIC(38,18) NOT NULL DEFAULT 0,available_balance NUMERIC(38,18) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS bashpay_audit_log(id BIGSERIAL PRIMARY KEY,actor_clerk_user_id TEXT,action TEXT NOT NULL,resource_type TEXT,resource_id TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bashpay_payment_intents(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES bashpay_users(id) ON DELETE CASCADE,tx_ref TEXT UNIQUE NOT NULL,provider_transaction_id TEXT,amount NUMERIC(38,18) NOT NULL,currency TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bashpay_virtual_accounts(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES bashpay_users(id) ON DELETE CASCADE,provider TEXT NOT NULL,currency TEXT NOT NULL,account_number TEXT,bank_name TEXT,tx_ref TEXT,provider_ref TEXT,status TEXT NOT NULL DEFAULT 'ACTIVE',expires_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bashpay_beneficiaries(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES bashpay_users(id) ON DELETE CASCADE,country TEXT NOT NULL,currency TEXT NOT NULL,bank_code TEXT NOT NULL,account_number TEXT NOT NULL,account_name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,country,currency,bank_code,account_number));
INSERT INTO bashpay_assets(code,name,type,decimals) VALUES('USD','US Dollar','fiat',2),('NGN','Nigerian Naira','fiat',2),('EUR','Euro','fiat',2),('GBP','British Pound','fiat',2),('USDT','Tether','crypto',6),('BTC','Bitcoin','crypto',8) ON CONFLICT(code) DO NOTHING;
CREATE INDEX IF NOT EXISTS bashpay_wallet_user ON bashpay_wallets(user_id,asset_id);
CREATE INDEX IF NOT EXISTS bashpay_tx_user ON bashpay_transactions(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS bashpay_transfer_user ON bashpay_transfers(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS bashpay_space_user ON bashpay_spaces(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS bashpay_admin_security(id INTEGER PRIMARY KEY CHECK(id=1),code4_hash TEXT NOT NULL,code14_hash TEXT NOT NULL,master8_hash TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());

CREATE TABLE IF NOT EXISTS bashpay_webhook_events(id BIGSERIAL PRIMARY KEY,provider TEXT NOT NULL,event_id TEXT UNIQUE,event_type TEXT,payload JSONB NOT NULL DEFAULT '{}'::jsonb,status TEXT NOT NULL DEFAULT 'RECEIVED',error TEXT,received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),processed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS bashpay_webhook_event_status ON bashpay_webhook_events(status,received_at DESC);
